def longest_unique_span(text):
    seen = set()
    left = 0
    best = 0
    for right, ch in enumerate(text):
        while ch in seen:
            seen.remove(text[left])
            left += 1
        seen.add(ch)
        if right - left + 1 > best:
            best = right - left + 1
    return best

