def min_positive_window(nums, target):
    left = 0
    total = 0
    best = float("inf")
    for right, value in enumerate(nums):
        total += value
        while total >= target:
            length = right - left + 1
            if length < best:
                best = length
            total -= nums[left]
            left += 1
    return 0 if best == float("inf") else best

